const equipe = '1025897_36728';
const prefixo = 'unidavi/iot/t27/' + equipe + '/';
const intervalo = 10000;
const janela = 30 * 60 * 1000;
const agora = Date.now();
const catalogo = {
    araucaria: {
        nome: 'Araucária', legada: 'Araucaria', cientifico: 'Araucaria angustifolia',
        cenario: 'Aquecimento e irrigação',
        regras: [
            ['temperatura', 'C', 50, 10, '<', 'aquecedor', 'aquecimento'],
            ['umidade-solo', '%', 100, 35, '<', 'irrigacao', 'irrigacao']
        ]
    },
    grandiuva: {
        nome: 'Grandiúva', legada: 'Grandiuva', cientifico: 'Trema micrantha',
        cenario: 'Irrigação e sombreamento leve',
        regras: [
            ['umidade-solo', '%', 100, 30, '<', 'irrigacao', 'irrigacao'],
            ['luminosidade', '%', 100, 90, '>', 'sombreamento', 'sombreamento']
        ]
    }
};
const cores = {OFFLINE:'#c62828', 'SEM DADOS':'#6b7280', ALERTA:'#ef6c00', ATUANDO:'#1976d2', NORMAL:'#2e7d32'};
const plantas = context.get('plantas') || {};
for (const especie of Object.keys(catalogo)) {
    plantas[especie] ||= {sensores:{}, atuadores:{}, placa:null, leituraDesde:0, estado:null, divergencias:{}};
}
let broker = context.get('broker') === true;
const gravacoes = [];
function registrar(tabela, especie, campos) {
    gravacoes.push({ tabela, payload: {equipe, especie, ...campos} });
}

if (msg.status) {
    const conectado = msg.status.fill === 'green' && msg.status.text === 'node-red:common.status.connected';
    if (conectado !== broker) {
        for (const planta of Object.values(plantas)) {
            planta.leituraDesde = agora;
            planta.divergencias = {};
            if (conectado) {
                planta.placaConfirmada = false;
                planta.atuadoresConfirmados = {};
            }
        }
    }
    broker = conectado;
    context.set('broker', broker);
} else if (msg.topic !== 'recalcular') {
    if (typeof msg.topic !== 'string' || !msg.topic.startsWith(prefixo)) return null;
    const partes = msg.topic.slice(prefixo.length).split('/');
    const [especie, categoria, nome] = partes;
    if (!Object.hasOwn(catalogo, especie)) return null;
    const planta = plantas[especie];
    const regras = catalogo[especie].regras;
    let dado = Buffer.isBuffer(msg.payload) ? msg.payload.toString() : msg.payload;
    const horario = new Date(agora).toISOString();

    if (categoria === 'status' && partes.length === 2) {
        if (dado !== 'online' && dado !== 'offline') return null;
        planta.placaConfirmada = true;
        if (planta.placa !== dado) {
            if (dado === 'offline') {
                planta.leituraDesde = agora;
                planta.divergencias = {};
            }
            planta.placa = dado;
            registrar('status_placa', especie, {status:dado, registrado_em:horario});
        }
    } else if (partes.length === 3) {
        try {
            if (typeof dado === 'string') dado = JSON.parse(dado);
        } catch {
            return null;
        }
        if (!dado || typeof dado !== 'object' || Array.isArray(dado)) return null;
        if (categoria === 'sensor') {
            const regra = regras.find(item => item[0] === nome);
            // O Mega também publica a temperatura do DHT22 na Grandiúva.
            const diagnostico = especie === 'grandiuva' && nome === 'temperatura';
            const unidade = regra?.[1] ?? (diagnostico ? 'C' : null);
            if (!unidade || msg.retain || dado.unidade !== unidade) return null;
            const valor = dado.valor;
            const limites = unidade === 'C' ? [-40, 80] : [0, 100];
            if (!Number.isFinite(valor) || valor < limites[0] || valor > limites[1]) return null;
            if (regra) {
                const sensor = planta.sensores[nome] ||= {pontos:[]};
                sensor.valor = valor;
                sensor.em = agora;
                sensor.pontos.push([agora, valor]);
            }
            registrar('leituras', especie, {sensor:nome, valor, unidade:dado.unidade, medido_em:horario});
        } else if (categoria === 'atuador') {
            const regra = regras.find(item => item[5] === nome || item[6] === nome);
            if (!regra || !['ligado','desligado'].includes(dado.estado)) return null;
            const atuador = regra[6];
            const ligado = dado.estado === 'ligado';
            planta.atuadoresConfirmados ||= {};
            planta.atuadoresConfirmados[atuador] = true;
            if (planta.atuadores[atuador]?.ligado !== ligado) {
                planta.atuadores[atuador] = {ligado, em:agora, retido:!!msg.retain};
                registrar('estados_atuadores', especie, {atuador, ligado, registrado_em:horario});
            }
        } else return null;
    } else return null;
}

function situacao(planta, sensores, atuadores, divergencias) {
    if (planta.placaConfirmada && planta.placa === 'offline') return ['OFFLINE', 'Placa desconectada.'];
    if (!broker) return ['SEM DADOS', 'Conexão do Node-RED com o broker indisponível.'];
    const faltando = sensores.find(sensor => sensor.em == null);
    if (faltando) return ['SEM DADOS', 'Aguardando leitura de ' + faltando.nome + '.'];
    const vencido = sensores.find(sensor => sensor.antigo);
    if (vencido) return ['SEM DADOS', vencido.nome + ': última leitura há ' + vencido.idade + ' s.'];
    if (atuadores.some(atuador => atuador.ligado == null)) return ['SEM DADOS', 'Aguardando estado dos atuadores.'];
    const alerta = divergencias.find(atuador => agora - planta.divergencias[atuador.nome] > 2 * intervalo);
    if (alerta) return ['ALERTA', alerta.nome + ': esperado ' + (alerta.esperado ? 'ligado.' : 'desligado.')];
    if (divergencias.length) {
        const anterior = ['NORMAL','ATUANDO'].includes(planta.estado) ? planta.estado : 'SEM DADOS';
        return [anterior, 'Conferindo a resposta de ' + divergencias.map(a => a.nome).join(', ') + '.'];
    }
    const ligados = atuadores.filter(a => a.ligado).map(a => a.nome);
    if (ligados.length) return ['ATUANDO', 'Em atuação: ' + ligados.join(', ') + '.'];
    return ['NORMAL', 'Todas as leituras na faixa verde.'];
}

const paineis = Object.entries(catalogo).map(([especie, cfg]) => {
    const planta = plantas[especie];
    const offline = planta.placaConfirmada && planta.placa === 'offline';
    const sensores = cfg.regras.map(([nome, unidade, max, limite, operador]) => {
        const sensor = planta.sensores[nome];
        if (sensor) sensor.pontos = sensor.pontos.filter(([em]) => em >= agora - janela);
        const em = sensor?.em ?? null;
        const idade = em == null ? null : Math.floor((agora - em) / 1000);
        const antigo = !broker || offline || em == null || em < planta.leituraDesde || agora - em > 3 * intervalo;
        const valor = sensor?.valor ?? null;
        const amarelo = '#fbc02d', verde = '#2e7d32';
        const inicio = operador === '<' ? amarelo : verde;
        const fim = operador === '<' ? verde : amarelo;
        const corte = limite / max * 180;
        return {nome, unidade:unidade === 'C' ? '°C' : unidade, max, limite, em, idade, valor, antigo,
            faixa: 'conic-gradient(from -90deg at 50% 100%, ' + inicio + ' 0deg ' + corte + 'deg, ' + fim + ' ' + corte + 'deg 180deg, transparent 180deg)',
            angulo: valor == null ? null : Math.max(0, Math.min(max, valor)) / max * 180 - 90,
            pontos: sensor?.pontos || []};
    });
    const atuadores = cfg.regras.map(([, , , limite, operador, topico, nome], i) => {
        const dado = planta.atuadores[nome];
        const sensor = sensores[i];
        const ligado = broker && !offline && planta.atuadoresConfirmados?.[nome] ? dado.ligado : null;
        const esperado = sensor.antigo ? null : operador === '<' ? sensor.valor < limite : sensor.valor > limite;
        const diverge = ligado != null && esperado != null && ligado !== esperado;
        if (diverge) planta.divergencias[nome] ??= agora;
        else delete planta.divergencias[nome];
        const verificacao = ligado == null || esperado == null ? '' :
            diverge ? (agora - planta.divergencias[nome] > 2 * intervalo ? 'Divergente' : 'Conferindo') : 'OK';
        return {nome, topico, ligado, esperado, diverge, verificacao, em:dado?.em, retido:dado?.retido,
            regra: sensor.nome + ' ' + operador + ' ' + limite + ' ' + sensor.unidade};
    });
    const [estado, motivo] = situacao(planta, sensores, atuadores, atuadores.filter(a => a.diverge));
    if (planta.estado !== estado) {
        planta.estado = estado;
        registrar('estados_gerais', especie, {estado, motivo, registrado_em:new Date(agora).toISOString()});
    }
    return {payload:{especie, nome:cfg.nome, cientifico:cfg.cientifico, cenario:cfg.cenario, equipe,
        estado, motivo, cor:cores[estado], broker, placa:broker && planta.placaConfirmada ? planta.placa : null,
        agora, ultima:Math.max(0, ...sensores.map(s => s.em || 0)), sensores, atuadores}};
});
context.set('plantas', plantas);
return [...paineis, gravacoes];

const base = String(env.get('SUPABASE_URL') || '').trim().replace(/\/$/, '');
const chave = String(env.get('SUPABASE_KEY') || '').trim();
const publica = chave.startsWith('sb_publishable_');
let anon = false;
if (chave.split('.').length === 3) {
    try { anon = JSON.parse(Buffer.from(chave.split('.')[1], 'base64url')).role === 'anon'; } catch {}
}
if (!/^https:\/\/[a-z0-9-]+\.supabase\.co$/i.test(base) || (!publica && !anon)) {
    if (!context.get('configInvalida')) {
        node.warn('Supabase: configure SUPABASE_URL e SUPABASE_KEY pública (anon ou publishable).');
        context.set('configInvalida', true);
    }
    return null;
}
context.set('configInvalida', false);
msg.method = 'POST';
msg.url = base + '/rest/v1/' + msg.tabela;
msg.headers = {'apikey':chave, 'Content-Type':'application/json', 'Prefer':'return=minimal'};
if (anon) msg.headers.Authorization = 'Bearer ' + chave;
msg.requestTimeout = 10000;
return msg;

if (msg.statusCode === 201 && !msg.error) {
    node.status({fill:'green',shape:'dot',text:'Última inserção confirmada'});
    return null;
}
const codigo = Number.isInteger(msg.statusCode) ? msg.statusCode : 'falha de transporte';
node.status({fill:'red',shape:'ring',text:'Falha ao gravar'});
return {payload:{servico:'Supabase', tabela:msg.tabela, codigo}};
